local M = class("RTARankRewardModel", LikeOO.OODataBase)

local __TAB_BTN_NODE = {
    {btn_key = "tog_1", configName = "flower_rank_reward", text_key = "tog_1_text", tabIndex = 1, tab_name = "flower_text_0054"}, 
    {btn_key = "tog_2", configName = "flower_guild_reward", text_key = "tog_2_text", tabIndex = 2, tab_name = "flower_text_0055"}, 
}

function M:onCreate()
    M.super.onCreate(self)
    self.m_open_tab_index = __TAB_BTN_NODE[1].tabIndex
    self.m_TabListData = __TAB_BTN_NODE
    self.m_versionId = self.m_params.version or 1
    self:setRankData()
    --self:setDashRankTabData()
    self.dataCountList = {}
    for index, itemData in pairs(self.m_rankAwards_data) do
        self.dataCountList[index] = #itemData
    end
    self:getData()
end

function M:onEnter()

end

function M:setRankData()
    if not self.m_rankAwards_data then
        self.m_rankAwards_data = {}
        for index = 1, table.nums(__TAB_BTN_NODE) do
            local itemData =  __TAB_BTN_NODE[index]
            local configXlsxData = ConfigManager:getCfgByName(itemData.configName)
            local cfgData = configXlsxData[self.m_versionId]
            if not self.m_rankAwards_data[index] then
                self.m_rankAwards_data[index] = {}
            end
            for _, itemData in pairs(cfgData) do
                table.insert(self.m_rankAwards_data[index], {
                   rank = itemData.rank,
                   award = itemData.rank_rewards,
                })
            end
        end
    end
end

return M
